.pm554-cm-kpi-label { display:block; font-size:11px; text-transform:uppercase; color:#718096; letter-spacing:.4px; }
.pm554-cm-kpi-val { display:block; font-size:22px; font-weight:700; color:#1a202c; margin:2px 0; }
.pm554-cm-budget { text-align:center; font-size:13px; color:#4a5568; margin-bottom:14px; }
.pm554-cm-insights-h { font-weight:700; margin-bottom:6px; color:#2d3748; }
.pm554-cm-insights { margin:0; padding-left:20px; }
